/* Retrieved results and user-owned follow-up jobs have separate lifecycles. */
const membershipFields=['inPool','archived','saved','savedAt','poolAddedAt','poolAddedBy','archivedAt'];
const statusFields=[...membershipFields,'status','date','note','applicationHistory'];
const beforePoolUndo=undoLast;
const beforePoolJdDetail=sourceJdDetail;
let manualJobDraft=null;
function hasApplication(j){return ['applied','interview','ended'].includes(j.status)||Boolean(j.date)||(j.applicationHistory||[]).some(x=>['applied','interview','ended'].includes(x.status))}
function activePool(){return state.jobs.filter(j=>j.inPool&&!j.archived)}
function archivedJobs(){return state.jobs.filter(j=>j.archived)}
function latestResults(){return [...new Set(state.resultIds||[])].map(job).filter(Boolean)}
function migratePool(){if(state.poolSchema===1)return;state.jobs.forEach(j=>{if(typeof j.inPool!=='boolean')j.inPool=Boolean(j.saved||j.status!=='pending'||j.greeting||j.note);j.archived=Boolean(j.archived);if(!j.manual&&!j.sourceKey&&demoJobs.some(d=>d.id===j.id))j.sourceKey='demo:'+j.id});state.resultIds=state.resultIds||state.jobs.filter(j=>!j.manual).map(j=>j.id);state.poolSchema=1}
function defaultFilters(tab='all'){return {q:'',city:'全部城市',role:'全部方向',days:'不限',tab,status:'all',match:'all',sort:'score',screen:'shown',archive:'active'}}
function screenJob(j){const bad=[],unknown=[];const p=state.profile;if(!j.city)unknown.push('工作地点未明确');else if(!['远程','不限'].includes(j.city)&&j.city!==p.city)bad.push(`城市 ${j.city}，意向 ${p.city}`);if(!Number.isFinite(j.days)||j.days<=0)unknown.push('每周到岗要求未明确');else if(j.days>Number(p.days))bad.push(`要求每周 ${j.days} 天，可到岗 ${p.days} 天`);if(!Number.isFinite(j.months)||j.months<=0)unknown.push('实习时长未明确');else if(j.months>Number(p.months))bad.push(`要求 ${j.months} 个月，可持续 ${p.months} 个月`);if(j.negotiable&&bad.length){unknown.push(...bad.map(x=>x+'，岗位说明可协商'));bad.length=0}if(j.manual)unknown.push('已保存原始 JD，内容匹配尚待分析');else if(needsEvidence(j))unknown.push('相关个人经历尚待核对');if(!j.manual&&!j.fit)unknown.push('岗位内容相关性尚未分析');return bad.length?{kind:'excluded',label:'条件不符',reasons:bad,tone:'red'}:unknown.length?{kind:'confirm',label:'需要确认',reasons:unknown,tone:'orange'}:{kind:'suggested',label:'建议了解',reasons:['已知到岗条件符合，有示例经历相关性，仍需查看原文'],tone:'green'}}
function scopedJobs(){if(page==='discover')return latestResults();if(page==='pool')return filter.archive==='archived'?archivedJobs():filter.archive==='saved'?activePool().filter(j=>j.saved):activePool();if(page==='applications')return state.jobs.filter(j=>j.inPool||hasApplication(j));return state.jobs}
function visibleJobs(){return scopedJobs().filter(j=>(!filter.q||(j.title+j.company+(j.tags||[]).join('')).toLowerCase().includes(filter.q.toLowerCase()))&&(filter.city==='全部城市'||j.city===filter.city)&&(filter.role==='全部方向'||j.role===filter.role)&&(filter.days==='不限'||Number.isFinite(j.days)&&j.days<=Number(filter.days))&&(filter.tab!=='saved'||j.inPool&&!j.archived&&j.saved)&&(filter.status==='all'||j.status===filter.status)&&(!filter.match||filter.match==='all'||filter.match==='priority'&&!conflicts(j).length&&Number.isFinite(j.score)&&j.score>=85||filter.match==='conflict'&&screenJob(j).kind==='excluded'||filter.match==='unknown'&&screenJob(j).kind==='confirm')&&(page!=='discover'||filter.screen==='all'||filter.screen==='shown'&&screenJob(j).kind!=='excluded'||filter.screen===screenJob(j).kind)).sort((a,b)=>filter.sort==='saved'?Number(b.savedAt||0)-Number(a.savedAt||0)||(b.score??-1)-(a.score??-1):(b.score??-1)-(a.score??-1))}
function clearResultFilters(){filter=defaultFilters();selected.clear();render()}
function resetFilters(){const archive=filter.archive;filter=defaultFilters(page==='pool'?'all':filter.tab);if(page==='pool')filter.archive=archive;selected.clear();render()}
function setScreen(v){filter.screen=v;selected.clear();render()}
function setArchive(v){if(!['active','saved','archived'].includes(v))return;filter.archive=v;filter.tab='all';selected.clear();render()}
function sidebar(){const entries=[['dashboard','grid','工作台',null],['discover','search','搜索结果',latestResults().length],['pool','brief','我的岗位池',activePool().length],['applications','send','我的投递',state.jobs.filter(hasApplication).length],['profile','user','个人档案',null]];return `<div class="logo"><span class="logo-mark">${icon('send')}</span>InternPilot</div><div class="nav-label">WORKSPACE</div>${entries.map(([p,i,n,count])=>`<button class="nav-item ${page===p?'active':''}" onclick="nav('${p}')">${icon(i)}${n}${count===null?'':`<span class="nav-count">${count}</span>`}</button>`).join('')}<div class="nav-label">PREFERENCES</div>${[['activity','history','历史活动'],['settings','settings','设置'],['design','board','设计说明']].map(([p,i,n])=>`<button class="nav-item ${page===p?'active':''}" onclick="nav('${p}')">${icon(i)}${n}</button>`).join('')}<div class="side-bottom"><div class="side-tip">${icon('filter')}<strong>搜索不等于保留</strong><p>先查看初筛结果，再选择加入岗位池。收藏标记其中的重点。</p><button onclick="openPoolRules()">查看入池规则 →</button></div><button class="account" onclick="openAccountMenu()" aria-label="打开账号菜单"><div class="avatar">${esc(state.profile.name.slice(-1))}</div><div><b>${esc(state.profile.name)}</b><small>演示账号 · 账号管理</small></div>${icon('down')}</button></div>`}
function statCards(){const a=activePool(),entries=[[latestResults().length,'搜索结果','search','获取后等待你选择'],[a.length,'我的岗位池','brief','主动保留并准备跟进'],[state.jobs.filter(j=>j.status==='applied').length,'已投递','send','包括归档中的历史记录'],[state.jobs.filter(j=>j.status==='interview').length,'面试中','chat','状态由用户确认']];return `<div class="stats">${entries.map(([v,n,i,t])=>`<div class="stat"><div class="stat-top"><span>${n}</span><span class="stat-icon">${icon(i)}</span></div><div class="stat-value">${v}<span class="stat-unit">个</span></div><div class="stat-bottom">${t}</div></div>`).join('')}</div>`}
function dashboard(){const a=activePool().filter(j=>j.status==='pending').sort((x,y)=>(y.score??-1)-(x.score??-1));return `${head('你的实习求职工作台','从系统找到的机会中，留下你准备跟进的岗位。',`<button class="button primary" onclick="openSearchConfig()">${icon('search')}搜索实习岗位</button>`)}${statCards()}<section class="pool-journey"><div><span>01 系统获取并初筛</span><strong>搜索结果 ${latestResults().length}</strong></div>${icon('arrow')}<div><span>02 用户选择保留</span><strong>我的岗位池 ${activePool().length}</strong></div>${icon('arrow')}<div><span>03 收藏重点并跟进</span><strong>收藏 ${activePool().filter(j=>j.saved).length}</strong></div></section><div class="section-head"><h2>岗位池中待跟进的机会</h2><button class="link-btn" onclick="nav('pool')">查看岗位池 ${icon('arrow')}</button></div><div class="jobs-grid">${a.length?a.slice(0,4).map(j=>jobCard(j)).join(''):empty('还没有待跟进的岗位','搜索结果经过你的选择后，才会进入岗位池。','去选择岗位',"nav('discover')")}</div><div class="below-grid"><section class="panel"><h3>明确下一步</h3><p class="muted">先查看初筛依据，再加入岗位池。缺少信息的岗位可以先保留，条件不符的岗位也允许你人工选择。</p><div class="inline"><button class="button soft" onclick="nav('discover')">查看搜索结果</button><button class="button" onclick="openManualJob()">手动添加岗位</button></div></section><section class="panel"><h3>最近活动</h3>${state.history.slice(0,3).map(h=>`<div class="activity-row"><span class="activity-dot"></span><div><b>${esc(h.title)}</b><small>${esc(h.time)}</small></div></div>`).join('')}</section></div>`}
function resultCounts(){const a=latestResults();return Object.fromEntries(['suggested','confirm','excluded'].map(k=>[k,a.filter(j=>screenJob(j).kind===k).length]))}
function discover(){const a=visibleJobs(),counts=resultCounts();return `${head('搜索结果','先核对条件和匹配依据，再决定哪些机会值得持续跟进。',`<button class="button primary" onclick="openSearchConfig()">${icon('search')}新建岗位搜索</button>`)}<section class="collection-summary"><div><strong>本批搜索结果 ${latestResults().length} 个，岗位池 ${activePool().length} 个</strong><p>搜索结果不会自动入池。可单个或批量加入；点击收藏会同时入池并标记重点。</p></div><button class="button soft" onclick="nav('pool')">我的岗位池 ${icon('chevron')}</button></section><div class="screen-tabs" aria-label="初筛结果">${[['shown','建议与待确认',counts.suggested+counts.confirm],['suggested','建议了解',counts.suggested],['confirm','需要确认',counts.confirm],['excluded','条件不符',counts.excluded],['all','全部结果',latestResults().length]].map(([v,n,count])=>`<button class="${filter.screen===v?'active':''}" aria-pressed="${filter.screen===v}" onclick="setScreen('${v}')">${n}<span>${count}</span></button>`).join('')}</div><div class="screen-rule-line"><span>${icon('info')}依据当前个人档案中的求职条件。信息缺失保留待确认，匹配分数不决定能否入池。</span><button class="link-btn" onclick="openPoolRules()">查看规则</button></div>${filtersBar()}${listToolbar(a)}${bulkBar()}${a.length?`<div class="jobs-grid">${a.map(j=>jobCard(j,true)).join('')}</div>`:empty('没有符合条件的岗位','可以清除筛选或查看全部结果，现有岗位池与投递记录不会清空。','查看全部搜索结果','clearResultFilters();setScreen(\'all\')')}${filter.screen==='shown'&&counts.excluded?`<button class="excluded-expand" onclick="setScreen('all')">${counts.excluded} 个条件不符的岗位已收起，展开查看并自行判断 ${icon('down')}</button>`:''}`}
function poolPage(){
  const a=visibleJobs(),view=filter.archive,favorites=view==='saved',archived=view==='archived';
  const savedCount=activePool().filter(j=>j.saved).length;
  const total=archived?archivedJobs().length:favorites?savedCount:activePool().length;
  const emptyTitle=total?(favorites?'收藏中没有符合条件的岗位':'没有符合条件的岗位'):favorites?'还没有收藏岗位':archived?'还没有归档岗位':'岗位池里还没有岗位';
  const emptyCopy=total?'可以清除当前筛选条件，查看此视图中的全部岗位。':favorites?'收藏用于标记岗位池中的重点机会，取消收藏后仍可在“全部跟进”中找到。':archived?'有投递历史的岗位移出岗位池后，会归档在这里，保留记录并可恢复。':'从搜索结果选择值得跟进的机会，或手动添加岗位。';
  const emptyAction=total?'清除筛选':favorites||archived?'查看全部跟进':'去发现岗位';
  const emptyHandler=total?'resetFilters()':favorites||archived?"setArchive('active')":"nav('discover')";
  return `${head('我的岗位池','只保留你决定跟进的岗位，收藏标记其中的重点。',`<button class="button primary" onclick="openManualJob()">${icon('plus')}手动添加岗位</button>`)}<section class="collection-summary"><div><strong>跟进中 ${activePool().length} 个岗位 · 收藏 ${savedCount} 个 · 已归档 ${archivedJobs().length} 个</strong><p>收藏是重点标记，取消收藏不会移出岗位池。有投递历史的岗位移出时会归档，记录随时可恢复。</p></div><button class="button" onclick="nav('discover')">继续发现岗位 ${icon('arrow')}</button></section><div class="tabs" role="group" aria-label="岗位池视图">${[['active','全部跟进',activePool().length],['saved','只看收藏',savedCount],['archived','已归档',archivedJobs().length]].map(([v,n,count])=>`<button class="tab ${view===v?'active':''}" aria-pressed="${view===v}" onclick="setArchive('${v}')">${n}<span class="num">${count}</span></button>`).join('')}</div>${filtersBar()}${listToolbar(a)}${bulkBar()}${a.length?`<div class="jobs-grid">${a.map(j=>jobCard(j,true)).join('')}</div>`:empty(emptyTitle,emptyCopy,emptyAction,emptyHandler)}`
}
function listToolbar(a){const scope=page==='discover'?'本批搜索结果':page==='pool'?({active:'全部跟进',saved:'只看收藏',archived:'已归档'}[filter.archive]):'当前列表';return `<div class="toolbar"><label class="inline"><input type="checkbox" class="selection-box" aria-label="全选当前筛选结果" ${a.length&&a.every(j=>selected.has(j.id))?'checked':''} ${a.length?'':'disabled'} onchange="selectAll(this.checked)">全选当前结果</label><span role="status">当前显示 ${a.length} 个岗位 · ${scope}</span></div>`}
function membershipButton(j){return j.archived?`<button class="button small" onclick="changePool([${j.id}],'add')">恢复跟进</button>`:j.inPool?`<span class="pool-membership">${icon('check')}已在岗位池</span>`:`<button class="button small primary" onclick="requestAddToPool([${j.id}])">${icon('plus')}加入岗位池</button>`}
function poolDetailControls(j){return `<div class="pool-detail-controls">${membershipButton(j)}${j.inPool&&!j.archived?`<button class="link-btn danger-text" onclick="requestPoolRemoval([${j.id}])">移出岗位池</button>`:''}</div>`}
function jobCard(j,selectable=false){const s=screenJob(j);return `<article class="job-card ${selected.has(j.id)?'selected':''} ${selectable?'selectable':''}">${selectable?`<input class="selection-box" type="checkbox" aria-label="选择${esc(j.title)}" ${selected.has(j.id)?'checked':''} onchange="selectJob(${j.id},this.checked)">`:''}<div class="company-row"><div class="company-logo" style="background:${j.bg||'#eeeafa'};color:${j.color||'#8a7ab8'}">${esc(j.initial||j.company.slice(0,1))}</div><div><div class="company-name">${esc(j.company)}</div><div class="company-meta">${esc(j.industry||'用户提供')} · ${j.manual?'手动添加':'演示岗位'}</div></div>${savedButton(j)}</div><div class="job-title-row"><h3 onclick="openJob(${j.id})">${esc(j.title)}</h3><span class="salary">${esc(j.pay||'薪资待确认')}</span></div><div class="job-meta"><span>${icon('pin')}${esc(j.city||'地点待确认')}</span><span>${icon('clock')}${j.days?j.days+' 天/周':'到岗待确认'} · ${j.months?j.months+' 个月':'时长待确认'}</span></div><div class="tags">${(j.tags||[]).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="screen-verdict ${s.kind}"><span class="tag ${s.tone}">${s.label}</span><p>${esc(s.reasons.join('；'))}</p></div><div class="card-bottom"><small>${hasApplication(j)||j.status==='ignored'?statusTag(j.status):Number.isFinite(j.score)?'示例匹配 '+j.score+' · 非入池门槛':'内容匹配待分析'}${j.archived?' · 已归档':''}</small><button class="button small soft" onclick="openJob(${j.id})">查看原文与匹配 ${icon('chevron')}</button></div><div class="pool-card-actions">${membershipButton(j)}${j.inPool&&!j.archived?`<button class="link-btn danger-text" onclick="requestPoolRemoval([${j.id}])">移出岗位池</button>`:''}</div></article>`}
function bulkBar(){const a=selectedVisibleJobs();if(!a.length)return '';return `<div class="bulk-bar"><span>已选择 <b>${a.length}</b> 个岗位</span><div class="inline">${a.some(j=>!j.inPool||j.archived)?'<button class="button small primary" onclick="requestAddToPool(selectedVisibleJobs().map(j=>j.id))">加入岗位池</button>':''}${a.some(j=>!j.saved)?'<button class="button small soft" onclick="bulkSaved(true)">收藏所选</button>':''}${a.some(j=>j.saved)?'<button class="button small" onclick="bulkSaved(false)">取消收藏</button>':''}${page==='discover'?'':`<button class="button small" onclick="bulkStatus('applied')">标记为已投递</button>`}${a.some(j=>j.inPool&&!j.archived)?'<button class="button small" onclick="requestPoolRemoval(selectedVisibleJobs().map(j=>j.id))">移出岗位池</button>':''}<button class="link-btn" onclick="selected.clear();render()">取消选择</button></div></div>`}
function poolSnapshot(j,fields=membershipFields){const x={id:j.id};for(const k of fields)x[k]=structuredClone(j[k]);return x}
function applySnapshot(j,snapshot,fields){for(const k of fields){if(snapshot[k]===undefined)delete j[k];else j[k]=structuredClone(snapshot[k])}}
function poolTransaction(ids,mutate,title,kind='pool',fields=membershipFields){const a=[...new Set(ids)].map(job).filter(Boolean);if(!a.length)return false;const previous=structuredClone(state),undo=lastUndo,changes=a.map(j=>poolSnapshot(j,fields));a.forEach(mutate);if(!addHistory(title,a.map(j=>j.company).join('、'))){state=previous;lastUndo=undo;return false}lastUndo={kind,changes,fields};selected.clear();return true}
function changePool(ids,mode='add'){const a=ids.map(job).filter(Boolean);const ok=poolTransaction(a.map(j=>j.id),j=>{if(mode==='add'){if(!j.inPool||j.archived)j.poolAddedAt=Date.now();j.inPool=true;j.archived=false;delete j.archivedAt;j.poolAddedBy='用户选择'}else if(hasApplication(j)){j.inPool=true;j.archived=true;j.archivedAt=Date.now()}else{j.inPool=false;j.archived=false;j.saved=false;delete j.savedAt;delete j.poolAddedAt}},mode==='add'?'已加入岗位池':'已移出或归档岗位');if(ok){refreshPoolView();toast(mode==='add'?`已将 ${a.length} 个岗位加入岗位池。`:'已移出未投递岗位，有投递历史的岗位已归档。',true)}return ok}
function requestAddToPool(ids){const a=[...new Set(ids)].map(job).filter(j=>j&&(!j.inPool||j.archived));if(!a.length){toast('所选岗位已经在岗位池。');return}const bad=a.filter(j=>screenJob(j).kind==='excluded');if(!bad.length){changePool(a.map(j=>j.id));return}modal='pool-confirm';showModal(`${modalHead('这些岗位存在条件冲突，仍然保留？','系统提供判断依据，是否加入由你决定。')}<div class="pool-warning-list">${bad.map(j=>`<div><strong>${esc(j.company+' · '+j.title)}</strong><p>${esc(screenJob(j).reasons.join('；'))}</p></div>`).join('')}</div><div class="footer"><button class="button" onclick="closeOverlay()">取消</button><button class="button primary" onclick="if(changePool(${JSON.stringify(a.map(j=>j.id))},'add'))closeOverlay()">仍加入岗位池</button></div>`)}
function requestPoolRemoval(ids){const a=[...new Set(ids)].map(job).filter(j=>j?.inPool&&!j.archived);if(!a.length)return;const history=a.filter(hasApplication);if(!history.length){changePool(a.map(j=>j.id),'remove');return}modal='pool-remove';showModal(`${modalHead('保留投递历史并归档？',`${history.length} 个岗位已有投递或面试记录。`)}<p class="pool-modal-copy">有历史记录的岗位将移到“已归档”，保留状态、日期、备注和文案。其余未投递岗位直接移出，操作后可撤回。</p><div class="footer"><button class="button" onclick="closeOverlay()">取消</button><button class="button primary" onclick="if(changePool(${JSON.stringify(a.map(j=>j.id))},'remove'))closeOverlay()">确认归档并保留记录</button></div>`)}
function refreshPoolView(){refreshCollections();for(const el of document.querySelectorAll?.('[data-pool-detail]')||[])el.innerHTML=poolDetailControls(job(el.dataset.poolDetail))}
function updateSaved(ids,value){const a=[...new Set(ids)].map(job).filter(j=>j&&(j.saved!==value||value&&(!j.inPool||j.archived)));return poolTransaction(a.map(j=>j.id),j=>{j.saved=value;if(value){j.savedAt=Date.now();if(!j.inPool||j.archived)j.poolAddedAt=Date.now();j.inPool=true;j.archived=false;delete j.archivedAt;j.poolAddedBy='收藏时加入'}else delete j.savedAt},value?'已收藏并保留岗位':'已取消重点收藏')}
function toggleSaved(id){const j=job(id);if(!j)return;const v=!j.saved;if(updateSaved([id],v)){refreshPoolView();toast(v?'已加入岗位池并标记收藏。':'已取消收藏，岗位仍保留在岗位池。',true)}}
function bulkSaved(v){const ids=selectedVisibleJobs().filter(j=>j.saved!==v||v&&!j.inPool).map(j=>j.id);if(updateSaved(ids,v)){refreshPoolView();toast(v?`已收藏 ${ids.length} 个岗位并加入岗位池。`:'已取消收藏，岗位和投递记录继续保留。',true)}}
function updateStatus(ids,s,date=today(),note=''){if(!statuses[s])return false;if(state.settings.failSave){state.settings.failSave=false;toast('模拟保存失败，原状态未改变，请重试。');return false}return poolTransaction(ids,j=>{j.status=s;if(['applied','interview','ended'].includes(s)){j.date=date;j.inPool=true;j.archived=false;delete j.archivedAt;j.poolAddedBy='确认投递后保留';j.applicationHistory=[...(j.applicationHistory||[]),{status:s,date,updated:today()}].slice(-30)}else if(s==='pending')delete j.date;if(note.trim())j.note=note.trim()},'已更新实际投递状态','status-pool',statusFields)}
undoLast=function(){if(!['pool','status-pool','manual-job'].includes(lastUndo?.kind)){beforePoolUndo();return}const u=lastUndo,previous=structuredClone(state);if(u.kind==='manual-job'&&u.created){const j=job(u.id);if(j){j.inPool=false;j.saved=false;j.archived=false;j.manualUndo=true}}else for(const old of u.changes||[]){const j=job(old.id);if(j)applySnapshot(j,old,u.fields||membershipFields)}if(!addHistory('已撤回岗位操作','恢复操作前的岗位选择或状态')){state=previous;return}lastUndo=null;refreshPoolView();toast('已恢复操作前的岗位选择和状态。')};
function applications(){const all=state.jobs.filter(j=>j.inPool||hasApplication(j)),a=visibleJobs();return `${head('我的投递','实际投递后手动记录。归档保留历史，搜索和收藏都不代表完成投递。',`<button class="button" onclick="nav('pool')">从岗位池选择</button>`)}<div class="tabs">${[['all','全部记录'],...Object.entries(statuses)].map(([v,n])=>`<button class="tab ${filter.status===v?'active':''}" onclick="setFilter('status','${v}')">${n}<span class="num">${v==='all'?all.length:all.filter(j=>j.status===v).length}</span></button>`).join('')}</div>${filtersBar()}${bulkBar()}${a.length?`<div class="table-wrap"><table class="jobs-table"><thead><tr><th><input type="checkbox" class="selection-box" aria-label="选择当前列表全部岗位" onchange="selectAll(this.checked)"></th><th>岗位／公司</th><th>申请状态</th><th>投递日期</th><th>保留状态</th><th>操作</th></tr></thead><tbody>${a.map(j=>`<tr><td><input type="checkbox" class="selection-box" aria-label="选择${esc(j.title)}" ${selected.has(j.id)?'checked':''} onchange="selectJob(${j.id},this.checked)"></td><td><button class="table-title" onclick="openJob(${j.id},'record')">${esc(j.title)}</button><div class="table-sub">${esc(j.company)}</div></td><td>${statusTag(j.status)}</td><td>${esc(j.date||'尚未记录')}</td><td>${j.archived?'已归档，记录保留':'跟进中'}</td><td><button class="link-btn" onclick="openStatusModal([${j.id}])">更新状态</button></td></tr>`).join('')}</tbody></table></div>`:empty('这个阶段还没有岗位','可以先将感兴趣的机会加入岗位池，再记录实际进展。','查看岗位池',"nav('pool')")}`}
function openPoolRules(){modal='pool-rules';showModal(`${modalHead('岗位初筛与入池规则','搜索结果和岗位池分别管理。')}<div class="pool-rule"><strong>建议了解</strong><p>已知硬条件符合，存在示例经历相关性。仍需核对原文。</p></div><div class="pool-rule"><strong>需要确认</strong><p>岗位条件、个人证据或内容分析不完整。未知不会直接判为不符合。</p></div><div class="pool-rule"><strong>条件不符</strong><p>已知城市、到岗天数或实习时长存在明确冲突，默认收起，允许人工保留。</p></div><div class="info-note">${icon('info')}<span>匹配分数不决定入池。选择“加入岗位池”、收藏，或确认实际投递后才保留。取消收藏只取消重点标记；有投递历史的岗位移出时归档。</span></div><div class="footer"><button class="button primary" onclick="closeOverlay()">知道了</button></div>`)}
function safeSourceUrl(value){const raw=String(value||'').trim();if(!raw)return '';try{const u=new URL(raw);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password?u.href:''}catch{return ''}}
function normalizedSource(value){const safe=safeSourceUrl(value);if(!safe)return '';const u=new URL(safe);for(const k of [...u.searchParams.keys()])if(/^utm_|^(ref|from|spm)$/i.test(k))u.searchParams.delete(k);u.searchParams.sort();return u.href.replace(/\/$/,'')}
function jobDuplicate(x){if(x.sourceKey){const found=state.jobs.find(j=>j.sourceKey===x.sourceKey);if(found)return found}const url=normalizedSource(x.sourceUrl);if(url){const found=state.jobs.find(j=>normalizedSource(j.sourceUrl)===url);if(found)return found}const key=t=>String(t||'').replace(/\s+/g,'').toLowerCase();const a=state.jobs.filter(j=>(!url||!normalizedSource(j.sourceUrl))&&key(j.company)===key(x.company)&&key(j.title)===key(x.title)&&(!x.city||!j.city||key(j.city)===key(x.city)));return a.length===1?a[0]:null}
function storeSearchResults(rows){const previous=structuredClone(state),ids=[];for(const source of rows){const x={...structuredClone(source),sourceKey:source.sourceKey||'demo:'+source.id};let j=jobDuplicate(x);if(!j){const id=Math.max(0,...state.jobs.map(j=>j.id))+1;j={...x,id,saved:false,status:'pending',inPool:false,archived:false,source:'招聘平台示例'};for(const k of ['date','note','greeting','savedAt','applicationHistory','poolAddedAt','poolAddedBy','archivedAt'])delete j[k];state.jobs.push(j)}else if(!j.manual){for(const k of ['title','company','city','days','months','pay','role','tags','fit','gap','sql','score'])if(x[k]!==undefined)j[k]=x[k]}j.lastRetrievedAt=Date.now();ids.push(j.id)}state.resultIds=[...new Set(ids)];state.searchCompletedAt=today();if(!addHistory('已整理搜索结果',`${state.resultIds.length} 个去重岗位，等待用户选择，不自动入池`)){state=previous;return false}return true}
function openTask(){modal='task';const saveError=task.status==='save-error',done=task.status==='done',blocked=task.status==='blocked',failed=task.status==='model-error',emptyState=task.status==='empty';showModal(`${modalHead('岗位搜索任务',task.running?'正在演示获取、去重和初筛，可以后台继续。':'查看结果与下一步操作')}<span class="tag purple">${esc(searchDraft?.city||state.profile.city)} · ${esc(searchDraft?.direction||state.profile.direction)}</span>${saveError?'<div class="error-banner">搜索结果保存失败，原岗位与投递记录已保留。请释放浏览器存储空间后重试。</div>':''}${blocked?'<div class="error-banner">登录状态失效，任务已暂停，现有岗位与投递记录保留。</div>':''}${failed?'<div class="error-banner">分析暂未完成，可以只重试分析，不重复加入岗位池。</div>':''}${['核对搜索范围','获取岗位原文','去重并整理搜索结果','初筛并等待用户选择'].map((t,i)=>`<div class="task-progress ${i<task.step?'done':i===task.step&&task.running?'running':''}"><span class="task-progress-icon">${i<task.step?icon('check'):i+1}</span><div><strong>${t}</strong><small>${i<task.step?'演示步骤完成':'等待或处理中'}</small></div></div>`).join('')}${done?`<div class="task-result">已整理 ${latestResults().length} 个搜索结果。未自动加入岗位池，原收藏和投递记录保持不变。</div>`:emptyState?'<div class="info-note">本次暂无结果，现有岗位池不会清空。</div>':''}<div class="footer"><button class="button" onclick="${task.running?'stopTask()':'closeOverlay()'}">${task.running?'停止任务':'关闭'}</button>${task.running?'<button class="button soft" onclick="closeOverlay()">后台继续</button>':done?'<button class="button primary" onclick="closeOverlay();nav(\'discover\')">查看初筛结果并选择</button>':blocked?'<button class="button primary" onclick="retryTask()">处理登录后重试</button>':failed?'<button class="button primary" onclick="retryAnalysis()">只重试分析</button>':emptyState?'<button class="button primary" onclick="openSearchConfig()">调整搜索范围</button>':'<button class="button" onclick="retryTask()">重新搜索</button>'}</div>`)}
function openManualJob(){manualJobDraft=null;modal='manual-job';showModal(`${modalHead('手动添加岗位','把其他渠道发现的机会加入岗位池，保留 JD 原文。')}<form onsubmit="reviewManualJob(event)"><div class="form-grid"><div class="field"><label>岗位名称</label><input class="input" name="title" required maxlength="100" placeholder="例如：设计实习生"></div><div class="field"><label>公司／机构</label><input class="input" name="company" required maxlength="100"></div><div class="field wide"><label>来源链接（可选）</label><input class="input" name="sourceUrl" type="url" placeholder="https://…"></div><div class="field"><label>工作地点（可选）</label><input class="input" name="city" maxlength="40" placeholder="未填写则待确认"></div><div class="field"><label>岗位方向（可选）</label><input class="input" name="role" maxlength="50" placeholder="不限岗位类型"></div><div class="field"><label>每周最低到岗要求</label><select class="select" name="days"><option value="">未明确，待确认</option>${[2,3,4,5].map(v=>`<option value="${v}">${v} 天</option>`).join('')}</select></div><div class="field"><label>最低实习时长</label><select class="select" name="months"><option value="">未明确，待确认</option>${[1,2,3,4,6].map(v=>`<option value="${v}">${v} 个月</option>`).join('')}</select></div><div class="field wide"><label>岗位 JD 原文</label><textarea class="input" name="sourceJd" required maxlength="10000" style="min-height:200px" placeholder="粘贴岗位职责、任职要求与实习安排，原型不会自动从链接抓取。"></textarea></div><label class="inline field wide"><input type="checkbox" name="negotiable">原文明确说明条件可协商</label></div><div class="info-note">${icon('info')}<span>根据你明确填写的条件做规则初筛。岗位内容的模型分析尚未接入，未填写的条件保留待确认。</span></div><div class="footer"><button class="button" type="button" onclick="closeOverlay()">取消</button><button class="button primary" type="submit">核对后添加</button></div></form>`,true)}
function prepareManualJob(v){const title=String(v.title||'').trim().slice(0,100),company=String(v.company||'').trim().slice(0,100),sourceJd=String(v.sourceJd||'').trim().slice(0,10000),raw=String(v.sourceUrl||'').trim(),sourceUrl=safeSourceUrl(raw);if(!title||!company||!sourceJd)return {error:'请填写岗位名称、公司和 JD 原文。'};if(raw&&!sourceUrl)return {error:'请填写有效的 http／https 来源链接。'};const n=x=>x===''||x==null?null:Number(x);const days=n(v.days),months=n(v.months);if(days!==null&&(!Number.isFinite(days)||days<1||days>7)||months!==null&&(!Number.isFinite(months)||months<1||months>24))return {error:'请检查到岗天数与实习时长。'};const x={title,company,sourceJd,sourceUrl,city:String(v.city||'').trim().slice(0,40),role:String(v.role||'').trim().slice(0,50)||title,days,months,negotiable:v.negotiable===true||v.negotiable==='on',manual:true,source:'用户手动添加'};const duplicate=jobDuplicate(x);return {record:duplicate?{...x,city:x.city||duplicate.city,days:days??duplicate.days,months:months??duplicate.months,sourceUrl:sourceUrl||duplicate.sourceUrl||''}:x,duplicateId:duplicate?.id||null}}
function reviewManualJob(e){e.preventDefault();manualJobDraft=prepareManualJob(Object.fromEntries(new FormData(e.target)));if(manualJobDraft.error){toast(manualJobDraft.error);return}showManualJobReview()}
function editManualJobDraft(){const x=manualJobDraft?.record;if(!x)return;openManualJob();for(const k of ['title','company','city','role','sourceUrl','sourceJd','days','months']){const el=document.querySelector(`[name="${k}"]`);if(el)el.value=x[k]??''}const el=document.querySelector('[name="negotiable"]');if(el)el.checked=Boolean(x.negotiable)}
function showManualJobReview(){const d=manualJobDraft;if(!d?.record)return;const x=d.record,s=screenJob(x);modal='manual-job';showModal(`${modalHead(d.duplicateId?'发现已存在的岗位':'核对并加入岗位池',d.duplicateId?'将更新你提供的岗位资料，保留已有收藏、文案与投递记录。':'确认后保留原始 JD，后续可继续核查匹配。')}<div class="manual-review"><h3>${esc(x.company+' · '+x.title)}</h3><span class="tag ${s.tone}">${s.label}</span><p>${esc(s.reasons.join('；'))}</p><div class="evidence-quote manual-jd-preview">${esc(x.sourceJd)}</div></div><div class="footer"><button class="button" onclick="editManualJobDraft()">返回修改</button><button class="button primary" onclick="commitManualJob()">${d.duplicateId?'确认更新并保留岗位':'确认添加到岗位池'}</button></div>`,true)}
function commitManualJob(){const d=manualJobDraft;if(!d?.record)return false;const previous=structuredClone(state),undo=lastUndo,x=d.record;let j=d.duplicateId?job(d.duplicateId):null;let changes=null;if(j){changes=[poolSnapshot(j,[...membershipFields,'title','company','city','days','months','role','sourceUrl','sourceJd','manual','negotiable','source','score','fit','gap'])];Object.assign(j,x);j.score=null;j.fit='保留用户更新的原文，等待内容分析。';j.gap='岗位内容尚待分析'}else{j={...x,id:Math.max(0,...state.jobs.map(y=>y.id))+1,status:'pending',saved:false,archived:false,score:null,tags:[],fit:'保留用户提供的原文，等待内容分析。',gap:'岗位内容尚待分析',initial:x.company.slice(0,1),bg:'#eeeafa',color:'#8a7ab8'};state.jobs.push(j)}j.inPool=true;j.archived=false;delete j.archivedAt;delete j.manualUndo;j.poolAddedAt=j.poolAddedAt||Date.now();j.poolAddedBy='手动添加';if(!addHistory(d.duplicateId?'已更新已有岗位资料':'已手动添加岗位',x.company+' · '+x.title)){state=previous;lastUndo=undo;return false}lastUndo={kind:'manual-job',created:!d.duplicateId,id:j.id,changes,fields:changes?Object.keys(changes[0]).filter(k=>k!=='id'):membershipFields};manualJobDraft=null;closeOverlay();nav('pool');toast(d.duplicateId?'已有岗位资料已更新，投递历史保留。':'岗位已加入岗位池，未自动收藏或标记投递。',true);return true}
function jdDetail(j){if(!j.manual)return beforePoolJdDetail(j);return `<div class="info-note">${icon('file')}<span>用户手动提供的岗位原文。尚未联网核验，也未调用模型分析。</span></div>${j.sourceUrl?`<a class="button small" target="_blank" rel="noopener noreferrer" href="${esc(safeSourceUrl(j.sourceUrl))}">${icon('external')}查看来源网页</a>`:''}<div class="jd-body manual-jd">${esc(j.sourceJd)}</div>`}
function matchDetail(j){const s=screenJob(j);const controls=`<div data-pool-detail="${j.id}">${poolDetailControls(j)}</div>`;if(!j.manual)return controls+baseMatchDetail(j);return `${controls}<div class="evidence-card"><div class="evidence-head"><strong>规则初筛</strong><span class="tag ${s.tone}">${s.label}</span></div><p>${esc(s.reasons.join('；'))}</p><p class="evidence-note">依据用户明确填写的条件，未知项保留待确认。岗位内容尚待分析，暂不生成匹配分数。</p></div><div class="evidence-quote manual-jd-preview">${esc(j.sourceJd)}</div><div class="info-note">${icon('chat')}<span>可以切换到岗位原文，选中文字向助手提问。</span></div>`}
function manualApply(id){const j=job(id),url=safeSourceUrl(j?.sourceUrl);if(url){window.open(url,'_blank','noopener,noreferrer');return}toast('示例岗位没有真实投递链接。手动添加岗位后可使用你提供的来源链接。')}
migratePool();
filter=defaultFilters();
